def round_price(x):
    sign = 1 if x >= 0 else -1
    abs_x = abs(x)
    scaled = abs_x * 100
    integer_part = int(scaled)
    fractional_part = scaled - integer_part

    if fractional_part > 0.5:
        rounded_scaled = integer_part + 1
    elif fractional_part < 0.5:
        rounded_scaled = integer_part
    else:
        rounded_scaled = integer_part + 1

    return sign * rounded_scaled / 100.0
